GIMMICKS.karakuri={name:"からくり仕掛けの間",icon:"⚙️",desc:"障害物が動きまわる。動く歯車に敵をぶつけよう。コイン×1.2",coin:1.2},GIMMICK_KEYS.push("karakuri"),GIMMICK_FIRST_RUN.push("karakuri");const KARAKURI_LAYOUTS=[{name:"往復",parts:[{kind:"bumper",path:t=>[.62*Math.sin(.018*t),-.42]},{kind:"bumper",path:t=>[.62*-Math.sin(.018*t),.42]},{kind:"spike",sprite:"gear",path:t=>[-.32,.6*Math.sin(.014*t)]},{kind:"spike",sprite:"gear",path:t=>[.32,.6*-Math.sin(.014*t)]}]},{name:"回転",parts:[0,1,2,3].map(i=>({kind:i%2?"bumper":"spike",sprite:i%2?null:"gear",path:t=>[.55*Math.cos(.011*t+i*Math.PI/2),.55*Math.sin(.011*t+i*Math.PI/2)]})).concat([{kind:"spike",sprite:"spikeBall",path:t=>[.2*Math.cos(.02*-t),.2*Math.sin(.02*-t)]}])},{name:"8の字",parts:[{kind:"spike",sprite:"spikeBall",path:t=>[.6*Math.sin(.012*t),.35*Math.sin(.024*t)]},{kind:"spike",sprite:"spikeBall",path:t=>[.6*-Math.sin(.012*t),.35*-Math.sin(.024*t)]},{kind:"bumper",path:t=>[.7*Math.cos(.009*t),.7*Math.sin(.009*t)]},{kind:"bumper",path:t=>[.7*Math.cos(.009*t+Math.PI),.7*Math.sin(.009*t+Math.PI)]}]}];let karakuriState=null;function karakuriPlace(){const L=KARAKURI_LAYOUTS[Math.abs(Math.floor(game.stage))%KARAKURI_LAYOUTS.length],r=Math.max(14,.1*arena.radius);obstacles=obstacles.filter(o=>"reflector"===o.kind||o.debug),L.parts.forEach((p,i)=>{const o={x:arena.x,y:arena.y,r:"bumper"===p.kind?.85*r:.9*r,seed:Math.random(),kind:p.kind,hp:1,cracks:[],karakuri:p.path};o.sprite=p.sprite||("bumper"===p.kind?"orb_"+ORB_COLORS[i%ORB_COLORS.length]:"gear"),obstacles.push(o)}),karakuriState={stage:obstacleStage,layout:L,t:0},karakuriMove(0),spawnDamageText(arena.x,arena.y-70,`⚙️ からくり起動！（${L.name}）`,"#9fe0ff",.01,!0);try{[0,120,240].forEach((at,i)=>setTimeout(()=>{thump(300+80*i,120,.08,.12,"square"),playTone(880+220*i,.05,"square",.04)},at))}catch(err){}}function karakuriMove(dt){const k=karakuriState;if(!k)return;k.t+=dt;const hx=arenaHalf(),hy=arenaHalfY();for(const o of obstacles){if(!o.karakuri)continue;const[px,py]=o.karakuri(k.t),nx=arena.x+px*(hx-o.r-6),ny=arena.y+py*(hy-o.r-6);o.kvx=nx-o.x,o.kvy=ny-o.y,o.x=nx,o.y=ny,o.mvx=0,o.mvy=0}}function tickKarakuri(){"function"!=typeof curGimmick||"karakuri"!==curGimmick()||game.skipChallenge?karakuriState&&(karakuriState=null,obstacles=obstacles.filter(o=>!o.karakuri)):karakuriState&&karakuriState.stage===obstacleStage&&obstacles.some(o=>o.karakuri)?karakuriMove("function"==typeof getEffectiveSpeed?getEffectiveSpeed():1):karakuriPlace()}{const orig=step;step=function(){try{tickKarakuri()}catch(err){console.warn(err)}return orig.apply(this,arguments)}}{const sel=document.getElementById("dbgGimmickSel");sel&&!sel.querySelector('option[value="karakuri"]')&&sel.insertAdjacentHTML("beforeend",`<option value="karakuri">${GIMMICKS.karakuri.icon} ${GIMMICKS.karakuri.name}</option>`)}